/*
 * Guide images embedded in the page as data URIs (like the MCP guide page), so they also show for a visitor
 * with no login. Chunks are generated by scripts/gen-public-images.py, one per page, loaded before the page renders.
 * An image that is not embedded falls back to the old attachment URL (works when logged in).
 */
import { localAsset } from './asset-map'
import { IMAGE_CHUNKS } from './images-index'

const EMBEDDED: Record<string, string> = {}

export async function loadImagesFor(key: string): Promise<void> {
    const load = IMAGE_CHUNKS[key]
    if (!load) return
    try {
        Object.assign(EMBEDDED, (await load()).default)
    } catch (err) {
        console.warn('[images] could not load embedded images for', key, err)
    }
}

export function publicAsset(url: string): string {
    let file = url.split('?')[0].split('/').pop() || ''
    try {
        file = decodeURIComponent(file)
    } catch {}
    return EMBEDDED[file] ?? localAsset(url)
}
